package com.trampolim.api.education;

import java.util.*;
import com.trampolim.api.radar.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class EducationRadarController {
 private final JdbcTemplate jdbc;private final LearningAccess access;private final RadarBridge bridge;
 public EducationRadarController(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,RadarBridge bridge){this.jdbc=jdbc;this.access=access;this.bridge=bridge;}
 @org.springframework.beans.factory.annotation.Autowired(required=false) private PassportOutbox passportOutbox;
 public record Export(UUID awardId,String challenge,boolean consent){}
 public record EvidenceQuery(List<UUID> receipts){}
 @GetMapping("/api/capacita/learning/radar/exports")public List<Map<String,Object>> exports(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT e.id,e.award_id,e.status,e.consent_at,a.name,a.skill_code FROM learning_radar_exports e JOIN learning_competency_awards a ON a.id=e.award_id WHERE e.student_id=? ORDER BY e.consent_at DESC LIMIT 100",access.account(email).id());}
 @org.springframework.transaction.annotation.Transactional("capacitaTransactionManager")@DeleteMapping("/api/capacita/learning/radar/exports/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email,@PathVariable UUID id){if(jdbc.update("UPDATE learning_radar_exports SET status='REVOKED',updated_at=CURRENT_TIMESTAMP WHERE id=? AND student_id=?",id,access.account(email).id())==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(passportOutbox!=null)passportOutbox.enqueue(id);}
 @PostMapping("/api/capacita/learning/radar/exports")public Map<String,Object> export(@AuthenticationPrincipal String email,@RequestBody Export input){
  bridge.configured();long uid=access.account(email).id();if(input==null||!input.consent()||input.awardId()==null||input.challenge()==null||!input.challenge().matches("[a-f0-9]{64}"))RadarModel.bad("Informe a conquista, o código gerado em Oportunidades e confirme o consentimento.");
  var awards=jdbc.queryForList("SELECT a.* FROM learning_competency_awards a JOIN learning_assessment_attempts t ON t.id=a.attempt_id AND t.student_id=a.student_id WHERE a.id=? AND a.student_id=? AND a.skill_code IS NOT NULL AND t.status='SUBMITTED' AND t.passed=TRUE AND a.revoked_at IS NULL AND (a.valid_until IS NULL OR a.valid_until>CURRENT_TIMESTAMP) AND t.assessment_id=a.assessment_id AND t.score_percent=a.score_percent",input.awardId(),uid);if(awards.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Use uma competência própria, aprovada e vinculada ao catálogo pelo professor. Conquistas antigas sem vínculo não são convertidas automaticamente.");var award=awards.get(0);String hash=RadarBridge.hash(input.challenge());
  // Durable PENDING receipt survives timeout after the destination committed; retry reuses its ID.
  jdbc.update("WITH owner AS (SELECT id FROM student_users WHERE id=? FOR NO KEY UPDATE) INSERT INTO learning_radar_exports(id,award_id,student_id,challenge_hash,status) SELECT ?,?,?,?,'PENDING' FROM owner WHERE (SELECT count(*) FROM learning_radar_exports e WHERE e.student_id=owner.id AND e.status<>'REVOKED')<100 ON CONFLICT(challenge_hash) DO NOTHING",uid,UUID.randomUUID(),input.awardId(),uid,hash);
  var receipts=jdbc.queryForList("SELECT * FROM learning_radar_exports WHERE challenge_hash=?",hash);if(receipts.isEmpty())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de vinculações ativas atingido.");var receipt=receipts.get(0);if(!Objects.equals(receipt.get("student_id"),uid)||!receipt.get("award_id").equals(input.awardId())||"REVOKED".equals(receipt.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código já utilizado ou revogado. Gere outro código.");
  var claim=new RadarService.Claim(input.challenge(),(UUID)receipt.get("id"),award.get("skill_code").toString(),((Number)award.get("skill_level")).intValue(),award.get("course_title").toString(),award.get("criterion").toString(),((java.sql.Timestamp)award.get("awarded_at")).toInstant().toString());
  bridge.post("/integrations/radar/award",claim);jdbc.update("UPDATE learning_radar_exports SET status='ACTIVE',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PENDING'",receipt.get("id"));if(passportOutbox!=null)passportOutbox.enqueue((UUID)receipt.get("id"));return Map.of("receiptId",receipt.get("id"),"status",jdbc.queryForObject("SELECT status FROM learning_radar_exports WHERE id=?",String.class,receipt.get("id")));
 }
 @PostMapping("/api/integrations/capacita/radar/evidence")public List<Map<String,Object>> evidence(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody EvidenceQuery input){bridge.authorize(key);if(input==null||input.receipts()==null||input.receipts().size()>100||input.receipts().stream().anyMatch(Objects::isNull))RadarModel.bad("Consulta de evidências inválida.");if(input.receipts().isEmpty())return List.of();
  String placeholders=String.join(",",Collections.nCopies(input.receipts().size(),"?"));var rows=jdbc.queryForList("SELECT e.id,a.skill_code,a.skill_level FROM learning_radar_exports e JOIN learning_competency_awards a ON a.id=e.award_id JOIN student_users u ON u.id=e.student_id JOIN learning_assessment_attempts t ON t.id=a.attempt_id WHERE e.id IN ("+placeholders+") AND e.status='ACTIVE' AND u.account_status='ACTIVE' AND u.email_verified=TRUE AND t.status='SUBMITTED' AND t.passed=TRUE AND a.revoked_at IS NULL AND (a.valid_until IS NULL OR a.valid_until>CURRENT_TIMESTAMP) AND t.assessment_id=a.assessment_id AND t.score_percent=a.score_percent",input.receipts().toArray());List<Map<String,Object>> result=new ArrayList<>();for(UUID id:input.receipts()){var row=rows.stream().filter(value->id.equals(value.get("id"))).findFirst();result.add(row.isPresent()?Map.of("receiptId",id,"active",true,"skillCode",row.get().get("skill_code"),"level",row.get().get("skill_level")):Map.of("receiptId",id,"active",false));}return result;
 }
 @GetMapping("/api/public/capacita/radar/training")public List<Map<String,Object>> training(@RequestParam String codes){var requested=Arrays.asList(codes.split(",",-1));if(requested.size()>40||requested.stream().anyMatch(code->!code.matches("[a-z][a-z0-9-]{1,63}")))RadarModel.bad("Competências inválidas.");var args=new ArrayList<Object>();List<String> predicates=new ArrayList<>();for(String code:requested){predicates.add("(v.definition->'competencies') @> ?::jsonb");args.add(bridge.encode(List.of(Map.of("skillCode",code))));}args.addAll(requested);
  return jdbc.queryForList("SELECT DISTINCT c.id AS course_id,c.title AS course_title,a.module_id,m.title AS module_title,x->>'skillCode' AS skill_code,(x->>'level')::int AS level FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id JOIN learning_courses c ON c.id=a.course_id JOIN student_users u ON u.id=c.teacher_id JOIN learning_modules m ON m.id=a.module_id CROSS JOIN LATERAL jsonb_array_elements(v.definition->'competencies') x WHERE a.status='PUBLISHED' AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND u.account_status='ACTIVE' AND ("+String.join(" OR ",predicates)+") AND x->>'skillCode' IN ("+String.join(",",Collections.nCopies(requested.size(),"?"))+") ORDER BY c.id DESC,a.module_id,skill_code LIMIT 40",args.toArray());
 }
}
